 */
async enhancePrompt(
  basePrompt: string,
  query: string,
  options?: RetrievalOptions
): Promise<string> {
  const retrievalResult = await this.retrieve(query, options);
  return buildEnhancedPrompt(basePrompt, retrievalResult);
}

